create table if not exists firefly_calendar_metadata (calendar_id varchar(128) not null, calendar_version bigint not null, jurisdiction varchar(64) not null default 'CUSTOM', published_at timestamp with time zone null, published_by varchar(128) null, primary key (calendar_id, calendar_version));
create table if not exists firefly_calendar_date_rule (calendar_id varchar(128) not null, calendar_version bigint not null, rule_date date not null, rule_kind varchar(16) not null, rule_name varchar(256) not null, source varchar(16) not null, locked boolean not null default false, import_id varchar(128) null, reason varchar(1024) not null, primary key (calendar_id, calendar_version, rule_date), foreign key (calendar_id, calendar_version) references firefly_calendar(calendar_id, calendar_version));
create table if not exists firefly_calendar_import (import_id varchar(128) primary key, calendar_id varchar(128) not null, target_version bigint not null, provider_id varchar(128) not null, provider_version varchar(128) not null, jurisdiction varchar(64) not null, zone_id varchar(128) not null, range_start date not null, range_end date not null, source_uri varchar(1024) not null, source_checksum varchar(128) not null, status varchar(32) not null, conflict_count integer not null default 0, imported_at timestamp with time zone not null, imported_by varchar(128) not null, published_at timestamp with time zone null);
create index if not exists idx_firefly_calendar_rule_date on firefly_calendar_date_rule(calendar_id, calendar_version, rule_date);
create index if not exists idx_firefly_calendar_import_status on firefly_calendar_import(calendar_id, status, imported_at);
